using System.Security.Cryptography;
using System.Text;
using Phrase.Acceptance.Tests.Support;
using Phrase.Adapters.CSharp;
using Phrase.Compiler;

namespace Phrase.Acceptance.Tests;

// Feature: Web stays an extension and existing apps keep their output
//   As Dana, I want the compiler to know which keywords are core and which
//   belong to the web extension, so that web concepts stay out of the core
//   while every existing app keeps working.
public class WebExtensionBoundary
{
    // SHA-256 of the generated file set for orders.phrase, recorded on the committed
    // tree before this slice. Paths are sorted ordinally. Each path and file text is
    // UTF-8, with a NUL byte after the path and after the text.
    private const string OrdersOutputHash = "409bf3c677d1b2f6f14e993085b272ebf0595795e4f571d208a9e55d39a9c721";

    [Fact]
    [Trait("Slice", "142")]
    public void Orders_phrase_loads_web_and_keeps_the_output_recorded_before_the_slice()
    {
        // Given Dana's orders.phrase and the output hash recorded before this slice
        var source = Fixture.Read("orders.phrase");
        var withExplicitWeb = source.Replace("module Orders\n", "module Orders\nuses web\n", StringComparison.Ordinal);

        // When both files are compiled with the C# provider
        var output = PhraseCompiler.Compile(source, new CSharpProvider());
        var explicitOutput = PhraseCompiler.Compile(withExplicitWeb, new CSharpProvider());

        // Then orders.phrase loads the web extension and its generated bytes match the stored hash
        Assert.Equal(new[] { "core", "web" }, ExtensionLoad.Active(source));
        Assert.Equal(OrdersOutputHash, HashFiles(output.Files));

        // And an explicit uses web line is accepted and equivalent: same active set, same bytes
        Assert.NotEqual(source, withExplicitWeb);
        Assert.Equal(ExtensionLoad.Active(source), ExtensionLoad.Active(withExplicitWeb));
        Assert.Equal(OrdersOutputHash, HashFiles(explicitOutput.Files));
    }

    private static string HashFiles(IReadOnlyDictionary<string, string> files)
    {
        using var buffer = new MemoryStream();
        foreach (var path in files.Keys.OrderBy(key => key, StringComparer.Ordinal))
        {
            buffer.Write(Encoding.UTF8.GetBytes(path));
            buffer.WriteByte(0);
            buffer.Write(Encoding.UTF8.GetBytes(files[path]));
            buffer.WriteByte(0);
        }

        return Convert.ToHexString(SHA256.HashData(buffer.ToArray())).ToLowerInvariant();
    }
}
